# Code generated by Claude
"""Variance test of the VLM check with and without enum output (design plan 8, D5): the same image and prompt sent N times each way, the cache bypassed. LIVE calls; changes nothing in the project.

    python experiments/enum_variance.py [--n 10]

The image is the eagle image of the enum probe (the stored eagle image of the successful grip, experiments/llm_cache/ee889017...png) that answered YES as free text and NO with enum output in one
call. The prompt is the verbatim VLM check prompt for "Grasp the beaker". Mode "live" (the cache is never read) with a throw-away cache folder. Prints the YES count of each arm and every reply;
writes the same to data/logs/enum_variance_<time>.json.
"""

import argparse
import json
import sys
import tempfile
import time
from pathlib import Path

import cv2

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from src.llm_gemini import GeminiCaller, LLMCache  # noqa: E402
from src.mpvi_prompts import VLM_ANSWERS, VLM_CHECK_PROMPT, fill_prompt  # noqa: E402
from src.task_config import LLM_CFG  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
IMAGE = ROOT / "experiments" / "llm_cache" / "ee889017580b27204e917853d56c3f01d6f274d1ca0abbff871d81e288f89d62.png"


def main(n):
    img = cv2.cvtColor(cv2.imread(str(IMAGE)), cv2.COLOR_BGR2RGB)
    prompt = fill_prompt(VLM_CHECK_PROMPT, description="Grasp the beaker", completion_criteria="The beaker is held securely in the gripper")
    caller = GeminiCaller(LLM_CFG, "live", cache=LLMCache(tempfile.mkdtemp()), say=lambda *_: None)
    out = {"model": LLM_CFG["model"], "temperature": LLM_CFG["temperature"], "n": n, "image": IMAGE.name, "free_text": [], "enum": []}
    for arm, choices in (("free_text", None), ("enum", VLM_ANSWERS)):
        for k in range(n):
            try:
                text = caller.text_call(prompt, img, kind="vlm", version="enum-variance", choices=choices)
            except Exception as e:                                  # noqa: BLE001 - recorded as the reply of that call
                text = f"ERROR {type(e).__name__}: {str(e)[:150]}"
            out[arm].append(text)
            print(f"  {arm:9s} {k + 1:2d}/{n}: {text[:80]!r}", flush=True)
    for arm in ("free_text", "enum"):
        out[f"{arm}_yes"] = sum(t.strip().upper().startswith("YES") for t in out[arm])
        out[f"{arm}_errors"] = sum(t.startswith("ERROR") for t in out[arm])
    print(f"\nYES count of {n}: free text {out['free_text_yes']} (errors {out['free_text_errors']}), enum {out['enum_yes']} (errors {out['enum_errors']})")
    p = ROOT / "data" / "logs" / f"enum_variance_{time.strftime('%Y%m%d_%H%M%S')}.json"
    p.write_text(json.dumps(out, indent=1))
    print(f"written {p}")


if __name__ == "__main__":
    ap = argparse.ArgumentParser()
    ap.add_argument("--n", type=int, default=10)
    main(ap.parse_args().n)
